// 1분 이내 + 같은 화자 → 같은 블록
function groupMessages(msgs){
  const groups=[];
  for(const m of msgs){
    const last=groups[groups.length-1];
    const sameBlock=last&&m.speaker!=="choice"&&last.speaker===m.speaker&&last.userCode===m.userCode&&last.characterName===m.characterName&&m.timestamp-last.lastTimestamp<60000;
    if(sameBlock){last.lines.push(m.text);last.items.push(m);last.lastTimestamp=m.timestamp;}
    else groups.push({id:m.id,speaker:m.speaker,userCode:m.userCode,characterName:m.characterName,avatar:m.avatar,timestamp:m.timestamp,lastTimestamp:m.timestamp,lines:[m.text],items:[m]});
  }
  return groups;
}

// 인라인 style 속성 중 허용된 것만 통과시켜 안전하게 렌더링
// - position/z-index/background-image/cursor/filter 등은 화면을 덮는 가짜 UI(피싱)나
//   추적 픽셀에 악용될 수 있어 절대 허용하지 않습니다.
// - 아래 속성들은 배너/타이틀 카드 같은 꾸미기 용도로 위험성이 없어 허용합니다.
const ALLOWED_STYLE_PROPS = {
  color:1, "background-color":1, "font-weight":1, "font-style":1, "text-decoration":1,
  "text-align":1, display:1, padding:1, "box-shadow":1, "border-radius":1,
  "line-height":1, "letter-spacing":1, border:1,
};
// url(...)/expression(...)/javascript: 등이 값에 섞여 있으면 통째로 무시합니다.
const DANGEROUS_VALUE_PATTERN = /url\s*\(|expression\s*\(|javascript:|import|position\s*:/i;
function parseInlineStyle(styleStr){
  const out={};
  (styleStr||"").split(";").forEach(pair=>{
    const idx=pair.indexOf(":");
    if(idx<0) return;
    const k=pair.slice(0,idx).trim().toLowerCase();
    const v=pair.slice(idx+1).trim();
    if(ALLOWED_STYLE_PROPS[k]&&v&&!/[<>{}]/.test(v)&&!DANGEROUS_VALUE_PATTERN.test(v)){
      const camel=k.replace(/-([a-z])/g,(_,c)=>c.toUpperCase());
      out[camel]=v;
    }
  });
  return out;
}
// 마크다운 서식 파서: **굵게** *기울기* ~~취소선~~ __밑줄__ + <span style="..."> (롤20 스타일)
function parseFormat(text){
  const parts=[];
  const re=/<span style="([^"<>]*)">(.*?)<\/span>|\*\*(.+?)\*\*|\*(.+?)\*|~~(.+?)~~|__(.+?)__/g;
  let last=0,m;
  while((m=re.exec(text))!==null){
    if(m.index>last) parts.push({t:"text",v:text.slice(last,m.index)});
    if(m[1]!==undefined) parts.push({t:"span",style:m[1],v:m[2]});
    else if(m[3]!==undefined) parts.push({t:"bold",v:m[3]});
    else if(m[4]!==undefined) parts.push({t:"italic",v:m[4]});
    else if(m[5]!==undefined) parts.push({t:"strike",v:m[5]});
    else if(m[6]!==undefined) parts.push({t:"under",v:m[6]});
    last=m.index+m[0].length;
  }
  if(last<text.length) parts.push({t:"text",v:text.slice(last)});
  return parts;
}
function FormattedText({text,style={}}){
  const parts=parseFormat(text);
  return(
    <span style={style}>
      {parts.map((p,i)=>{
        if(p.t==="bold") return <strong key={i}>{p.v}</strong>;
        if(p.t==="italic") return <em key={i}>{p.v}</em>;
        if(p.t==="strike") return <s key={i}>{p.v}</s>;
        if(p.t==="under") return <u key={i}>{p.v}</u>;
        if(p.t==="span") return <span key={i} style={parseInlineStyle(p.style)}>{p.v}</span>;
        return <span key={i}>{p.v}</span>;
      })}
    </span>
  );
}

function MessageBlock({group,myUserCode,isGM,onEdit,onDelete,onPickChoice}){
  const{speaker,characterName,avatar,timestamp,lines,items}=group;
  const isAnon=speaker==="narrate"||speaker==="judge"||speaker==="system";
  const isJudge=speaker==="judge";
  const isDice=speaker==="dice";
  const isImg=speaker==="image";
  const isChoice=speaker==="choice";
  const isMine=group.userCode===myUserCode;

  // GM이 보낸 이미지: 서술처럼 아바타·이름 없이 가운데 정렬로 표시
  if(isImg){
    return(
      <div className="anon-msg" style={{display:"flex",flexDirection:"column",alignItems:"center",padding:"8px 4px",gap:5}}>
        {isMine&&(
          <span className="msg-actions" style={{display:"inline-flex",gap:3}}>
            <button type="button" onClick={()=>onDelete(items[0])} style={{background:"none",border:"none",cursor:"pointer",color:"var(--text-faint)",padding:0}}><Trash2 size={9}/></button>
          </span>
        )}
        {lines.map((line,i)=>(
          <img key={i} src={line} alt="전송된 이미지" style={{maxWidth:280,maxHeight:220,borderRadius:8,objectFit:"contain"}}/>
        ))}
      </div>
    );
  }

  // 선택지: GM이 등록한 여러 조사 스팟을 버튼으로 보여주고, 참가자가 누르면
  // "OO을/를 살핀다"가 자동으로 채팅에 남습니다. 한 번 고른 선택지는 회색으로 잠깁니다.
  if(isChoice){
    let data=null; try{data=JSON.parse(items[0].text);}catch{}
    if(!data) return null;
    return(
      <div style={{display:"flex",justifyContent:"center",padding:"8px 4px"}}>
        <div style={{maxWidth:"92%",border:"1.5px solid var(--accent)",borderRadius:14,background:"var(--bg-panel)",padding:"12px 14px",textAlign:"center"}}>
          <div style={{fontSize:11.5,color:"var(--accent-deep)",fontWeight:700,marginBottom:9,display:"flex",alignItems:"center",justifyContent:"center",gap:6}}>
            조사할 곳을 선택하세요
            {isGM&&isMine&&<button type="button" onClick={()=>onDelete(items[0])} style={{background:"none",border:"none",cursor:"pointer",color:"var(--text-faint)",padding:0,display:"flex"}}><Trash2 size={10}/></button>}
          </div>
          <div style={{display:"flex",flexWrap:"wrap",gap:7,justifyContent:"center"}}>
            {data.options.map(opt=>{
              const picked=data.picked?.[opt];
              return(
                <button key={opt} type="button" disabled={!!picked} onClick={()=>onPickChoice(group,opt)}
                  style={{
                    padding:"7px 14px",borderRadius:999,cursor:picked?"default":"pointer",
                    border:"1.5px solid "+(picked?"var(--border)":"var(--accent)"),
                    background:picked?"#fff":"var(--accent)",
                    color:picked?"var(--text-faint)":"#fff",
                    fontSize:13,fontWeight:600,
                    textDecoration:picked?"line-through":"none",
                  }}>
                  {opt}
                </button>
              );
            })}
          </div>
        </div>
      </div>
    );
  }

  // 서술: 헤더 없이 중앙 정렬, 그냥 텍스트만
  // 판정 요청(GM이 판정을 걸 때): 서술과 같이 중앙 정렬하되, 눈에 띄도록 둥근 블록으로 감쌈
  // 수정·삭제는 GM 전용, 마우스를 올렸을 때만 표시
  if(isAnon){
    const editButtons=isGM&&isMine&&(
      <span className="msg-actions" style={{position:"absolute",left:"100%",top:"50%",transform:"translateY(-50%)",marginLeft:6,display:"inline-flex",gap:3,whiteSpace:"nowrap"}}>
        {items.length===1&&<button type="button" onClick={()=>onEdit(items[0])} style={{background:"none",border:"none",cursor:"pointer",color:"var(--text-faint)",padding:0}}><Pencil size={9}/></button>}
        <button type="button" onClick={()=>onDelete(items[0])} style={{background:"none",border:"none",cursor:"pointer",color:"var(--text-faint)",padding:0}}><Trash2 size={9}/></button>
      </span>
    );
    if(isJudge){
      return(
        <div className="anon-msg" style={{display:"flex",justifyContent:"center",padding:"6px 4px"}}>
          <div style={{position:"relative",display:"inline-flex",alignItems:"center",maxWidth:"92%",border:"1.5px solid var(--accent)",borderRadius:999,background:"var(--bg-panel)",padding:"8px 18px",textAlign:"center"}}>
            <span style={{fontSize:14.5,color:"var(--accent-deep)",fontWeight:600}}>
              {lines.map((line,i)=>(
                <span key={i}>
                  <FormattedText text={line}/>
                  {i<lines.length-1&&<br/>}
                </span>
              ))}
            </span>
            {editButtons}
          </div>
        </div>
      );
    }
    return(
      <div className="anon-msg" style={{display:"flex",justifyContent:"center",padding:"10px 4px"}}>
        <div style={{position:"relative",display:"inline-block",textAlign:"center",lineHeight:1.8}}>
          {lines.map((line,i)=>(
            <div key={i} style={{fontSize:14.5,color:"var(--text)",whiteSpace:"pre-wrap",marginTop:i>0?12:0}}>
              <FormattedText text={line}/>
            </div>
          ))}
          {editButtons}
        </div>
      </div>
    );
  }

  return(
    <div style={{display:"flex",gap:9,padding:"5px 0"}}>
      <div style={{width:28,height:28,borderRadius:"50%",overflow:"hidden",background:"var(--bg-panel)",flexShrink:0,border:"1px solid var(--border)",marginTop:1}}>
        {avatar?<img src={avatar} style={{width:"100%",height:"100%"}} className="coc-avatar"/>:<Sparkles size={11} color="var(--accent-soft)" style={{margin:8}}/>}
      </div>
      <div style={{flex:1,minWidth:0}}>
        <div style={{display:"flex",gap:7,alignItems:"center",marginBottom:3}}>
          {/* NPC도 일반 캐릭터와 동일하게 */}
          {(speaker==="ic"||speaker==="npc"||isDice)&&<span style={{color:"var(--accent-deep)",fontWeight:600,fontSize:12.5}}>{characterName}</span>}
          {speaker==="ooc"&&<span style={{color:"var(--text-dim)",fontSize:12.5}}>{characterName} <span className="coc-mono" style={{fontSize:10}}>OOC</span></span>}
          <span className="coc-mono" style={{fontSize:10.5,color:"var(--text-faint)"}}>{fmtTime(timestamp)}</span>
          {isMine&&!isDice&&(
            <span className="msg-actions" style={{display:"flex",gap:2,marginLeft:1}}>
              {items.length===1&&<button type="button" onClick={()=>onEdit(items[0])} style={{background:"none",border:"none",cursor:"pointer",color:"var(--text-faint)",padding:"0 2px",display:"flex"}} title="수정"><Pencil size={9}/></button>}
              <button type="button" onClick={()=>onDelete(items[0])} style={{background:"none",border:"none",cursor:"pointer",color:"#c05050",padding:"0 2px",display:"flex"}} title="삭제"><Trash2 size={9}/></button>
            </span>
          )}
        </div>
        <div style={{display:"flex",flexDirection:"column",gap:3}}>
          {lines.map((line,i)=>{
            if(isDice) return <DiceCard key={i} line={line}/>;
            return <div key={i} style={{fontSize:14.5,whiteSpace:"pre-wrap",wordBreak:"break-word"}}><FormattedText text={line}/></div>;
          })}
        </div>
      </div>
    </div>
  );
}

/* ============================== 선택지(조사 스팟) ============================== */

function ChoiceCreatorModal({onClose,onCreate}){
  const [options,setOptions]=useState([]);
  const [input,setInput]=useState("");
  const [creating,setCreating]=useState(false);

  const addOption=()=>{
    const v=input.trim();
    if(!v||options.includes(v))return;
    setOptions(o=>[...o,v]);setInput("");
  };
  const removeOption=i=>setOptions(o=>o.filter((_,idx)=>idx!==i));
  const create=async()=>{
    if(options.length<2)return;
    setCreating(true);
    await onCreate(options);
    setCreating(false);
  };

  return(
    <div className="coc-modal-backdrop" onClick={onClose}>
      <div className="coc-modal" style={{maxWidth:420}} onClick={e=>e.stopPropagation()}>
        <div style={{padding:20}}>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14}}>
            <div className="coc-display" style={{fontSize:16,color:"var(--accent-deep)"}}>선택지 만들기</div>
            <button className="coc-btn ghost small" onClick={onClose} style={{padding:6}}><X size={13}/></button>
          </div>
          <div style={{fontSize:12.5,color:"var(--text-faint)",marginBottom:12}}>
            조사할 곳을 하나씩 입력하고 Enter를 눌러 추가하세요. (예: 소파, 침대, 책장, 서랍)
          </div>
          <div style={{display:"flex",gap:7,marginBottom:12}}>
            <input className="coc-input" value={input} onChange={e=>setInput(e.target.value)}
              onKeyDown={e=>{if(e.key==="Enter"){e.preventDefault();addOption();}}}
              placeholder="조사할 곳 이름" autoFocus/>
            <button type="button" className="coc-btn small" onClick={addOption} disabled={!input.trim()}>추가</button>
          </div>
          {options.length>0&&(
            <div style={{display:"flex",flexWrap:"wrap",gap:7,marginBottom:16}}>
              {options.map((o,i)=>(
                <div key={i} style={{display:"flex",alignItems:"center",gap:5,background:"var(--bg-panel)",border:"1px solid var(--border)",borderRadius:999,padding:"5px 6px 5px 12px",fontSize:13}}>
                  {o}
                  <button type="button" onClick={()=>removeOption(i)} style={{background:"none",border:"none",cursor:"pointer",color:"var(--text-faint)",padding:"0 3px",fontSize:14,lineHeight:1}}>×</button>
                </div>
              ))}
            </div>
          )}
          {options.length===1&&<div style={{fontSize:11.5,color:"var(--text-faint)",marginBottom:10}}>선택지는 2개 이상부터 만들 수 있어요.</div>}
          <button type="button" className="coc-btn" style={{width:"100%",justifyContent:"center",padding:11}} disabled={options.length<2||creating} onClick={create}>
            {creating?"만드는 중...":`선택지 ${options.length}개로 만들기`}
          </button>
        </div>
      </div>
    </div>
  );
}

/* ============================== 핸드아웃 ============================== */

function HandoutManagerModal({room,userCode,handouts,roomParticipants,onClose}){
  const [showCreate,setShowCreate]=useState(false);
  const [title,setTitle]=useState("");
  const [text,setText]=useState("");
  const [image,setImage]=useState("");
  const [saving,setSaving]=useState(false);
  const [assigning,setAssigning]=useState(null);
  const [selection,setSelection]=useState({});
  const imgRef=useRef(null);

  const createHandout=async()=>{
    const t=title.trim();if(!t)return;
    setSaving(true);
    const id=newId();
    const handout={id,roomId:room.id,title:t,text:text.trim(),image,creatorCode:userCode,createdAt:Date.now(),visibleTo:[]};
    await storeSet(`handout:${room.id}:${id}`,handout,true);
    setSaving(false);setShowCreate(false);setTitle("");setText("");setImage("");
  };
  const deleteHandout=async h=>{
    if(!window.confirm(`'${h.title}' 핸드아웃을 삭제하시겠습니까?`))return;
    await storeDelete(`handout:${room.id}:${h.id}`,true);
  };
  const openAssign=h=>{
    setAssigning(h);
    const sel={};(h.visibleTo||[]).forEach(c=>sel[c]=true);setSelection(sel);
  };
  const saveAssign=async()=>{
    const visibleTo=Object.entries(selection).filter(([,v])=>v).map(([c])=>c);
    await storeSet(`handout:${room.id}:${assigning.id}`,{...assigning,visibleTo},true);
    setAssigning(null);
  };

  return(
    <div className="coc-modal-backdrop" onClick={onClose}>
      <div className="coc-modal" onClick={e=>e.stopPropagation()}>
        <div style={{padding:20}}>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:16}}>
            <div className="coc-display" style={{fontSize:16,color:"var(--accent-deep)"}}>핸드아웃 관리</div>
            <button className="coc-btn ghost small" onClick={onClose} style={{padding:6}}><X size={13}/></button>
          </div>

          {assigning?(
            <div>
              <button className="coc-btn ghost small" onClick={()=>setAssigning(null)} style={{marginBottom:12}}><ArrowLeft size={12}/> 목록으로</button>
              <div className="coc-display" style={{fontSize:14.5,marginBottom:4}}>{assigning.title}</div>
              <div className="coc-label" style={{marginBottom:8}}>누구에게 보여줄까요?</div>
              {roomParticipants.length===0?(
                <div style={{fontSize:12.5,color:"var(--text-faint)",marginBottom:14}}>아직 캐릭터를 만든 참가자가 없어요.</div>
              ):(
                <div style={{display:"flex",flexDirection:"column",gap:8,marginBottom:16}}>
                  {roomParticipants.map(code=>(
                    <label key={code} style={{display:"flex",alignItems:"center",gap:8,fontSize:14,cursor:"pointer",padding:"8px 10px",background:"var(--bg-panel)",borderRadius:8}}>
                      <input type="checkbox" checked={!!selection[code]} onChange={e=>setSelection(s=>({...s,[code]:e.target.checked}))} style={{width:16,height:16,cursor:"pointer"}}/>
                      {code}
                    </label>
                  ))}
                </div>
              )}
              <button type="button" className="coc-btn" style={{width:"100%",justifyContent:"center",padding:11}} onClick={saveAssign}>전송</button>
            </div>
          ):showCreate?(
            <div>
              <button className="coc-btn ghost small" onClick={()=>setShowCreate(false)} style={{marginBottom:12}}><ArrowLeft size={12}/> 목록으로</button>
              <div className="coc-label" style={{marginBottom:5}}>제목</div>
              <input className="coc-input" value={title} onChange={e=>setTitle(e.target.value)} placeholder="예: 낡은 편지" style={{marginBottom:12}} autoFocus/>
              <div className="coc-label" style={{marginBottom:5}}>내용</div>
              <textarea className="coc-input" rows={5} value={text} onChange={e=>setText(e.target.value)} placeholder="플레이어에게 보여줄 글 내용" style={{marginBottom:12}}/>
              <div className="coc-label" style={{marginBottom:5}}>사진 (선택)</div>
              <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:16}}>
                {image&&<img src={image} style={{width:56,height:56,borderRadius:8,objectFit:"cover",border:"1px solid var(--border)"}}/>}
                <button type="button" className="coc-btn ghost small" onClick={()=>imgRef.current?.click()}><Camera size={12}/> 사진 첨부</button>
                {image&&<button type="button" className="coc-btn ghost small" onClick={()=>setImage("")}>제거</button>}
              </div>
              <input ref={imgRef} type="file" accept="image/*" style={{display:"none"}}
                onChange={async e=>{const f=e.target.files?.[0];if(!f)return;setImage(await fileToResizedDataURL(f,640));e.target.value="";}}/>
              <button type="button" className="coc-btn" style={{width:"100%",justifyContent:"center",padding:11}} disabled={!title.trim()||saving} onClick={createHandout}>
                {saving?"저장 중...":"핸드아웃 만들기"}
              </button>
            </div>
          ):(
            <div>
              <button type="button" className="coc-btn" style={{width:"100%",justifyContent:"center",padding:11,marginBottom:16}} onClick={()=>setShowCreate(true)}>
                <Plus size={13}/> 새 핸드아웃 추가
              </button>
              {handouts.length===0?(
                <div style={{color:"var(--text-faint)",fontSize:13,textAlign:"center",padding:24}}>아직 만든 핸드아웃이 없어요.</div>
              ):(
                <div style={{display:"flex",flexDirection:"column",gap:8}}>
                  {handouts.map(h=>(
                    <div key={h.id} className="coc-card" style={{padding:12,display:"flex",alignItems:"center",gap:10}}>
                      {h.image?<img src={h.image} style={{width:40,height:40,borderRadius:6,objectFit:"cover",flexShrink:0}}/>:
                        <div style={{width:40,height:40,borderRadius:6,background:"var(--bg-panel)",flexShrink:0}}/>}
                      <div style={{flex:1,minWidth:0}}>
                        <div style={{fontSize:14,fontWeight:600,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{h.title}</div>
                        <div className="coc-mono" style={{fontSize:11,color:"var(--text-faint)"}}>
                          {(h.visibleTo||[]).length>0?`공개 대상: ${h.visibleTo.join(", ")}`:"아직 공개 안 됨"}
                        </div>
                      </div>
                      <button type="button" className="coc-btn small" onClick={()=>openAssign(h)}>전송</button>
                      <button type="button" onClick={()=>deleteHandout(h)} style={{background:"none",border:"none",cursor:"pointer",color:"var(--text-faint)",padding:4}}><Trash2 size={13}/></button>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

function HandoutViewerModal({handouts,onClose}){
  const [viewing,setViewing]=useState(null);
  return(
    <div className="coc-modal-backdrop" onClick={onClose}>
      <div className="coc-modal" onClick={e=>e.stopPropagation()}>
        <div style={{padding:20}}>
          {viewing?(
            <div>
              <button className="coc-btn ghost small" onClick={()=>setViewing(null)} style={{marginBottom:12}}><ArrowLeft size={12}/> 목록으로</button>
              <div className="coc-display" style={{fontSize:17,color:"var(--accent-deep)",marginBottom:12}}>{viewing.title}</div>
              {viewing.image&&<img src={viewing.image} style={{width:"100%",borderRadius:10,border:"1px solid var(--border)",marginBottom:12}}/>}
              {viewing.text&&<div style={{fontSize:14.5,whiteSpace:"pre-wrap",lineHeight:1.6}}>{viewing.text}</div>}
            </div>
          ):(
            <div>
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:16}}>
                <div className="coc-display" style={{fontSize:16,color:"var(--accent-deep)"}}>핸드아웃</div>
                <button className="coc-btn ghost small" onClick={onClose} style={{padding:6}}><X size={13}/></button>
              </div>
              {handouts.length===0?(
                <div style={{color:"var(--text-faint)",fontSize:13,textAlign:"center",padding:24}}>아직 받은 핸드아웃이 없어요.</div>
              ):(
                <div style={{display:"flex",flexDirection:"column",gap:8}}>
                  {handouts.map(h=>(
                    <div key={h.id} className="coc-card" style={{padding:12,display:"flex",alignItems:"center",gap:10,cursor:"pointer"}} onClick={()=>setViewing(h)}>
                      {h.image?<img src={h.image} style={{width:44,height:44,borderRadius:8,objectFit:"cover",flexShrink:0}}/>:
                        <div style={{width:44,height:44,borderRadius:8,background:"var(--bg-panel)",flexShrink:0}}/>}
                      <div style={{fontSize:14.5,fontWeight:600}}>{h.title}</div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

/* ============================== 배너 만들기 ============================== */
// 한 줄 안에 색이 다른 여러 단어를 섞고 싶을 수 있어서, "조각(세그먼트)"을 하나씩
// 쌓아서 한 줄로 이어붙이는 방식으로 만들었습니다. 각 조각은 스타일 있는 단어이거나
// 그냥 이어주는 일반 텍스트일 수 있습니다. 완성되면 그 한 줄 전체를 채팅 입력창에 넣습니다.

function BannerBuilderModal({onClose,onInsert}){
  const savedPrefs=loadBannerPrefs();
  const [segments,setSegments]=useState([]); // [{id,text,styled,color,useBg,bgColor,bold,italic,underline}]
  const [draftText,setDraftText]=useState("");
  const [styled,setStyled]=useState(savedPrefs?.styled??true);
  const [color,setColor]=useState(savedPrefs?.color??"#355C9F");
  const [useBg,setUseBg]=useState(savedPrefs?.useBg??false);
  const [bgColor,setBgColor]=useState(savedPrefs?.bgColor??"#355C9F");
  const [bold,setBold]=useState(savedPrefs?.bold??false);
  const [italic,setItalic]=useState(savedPrefs?.italic??false);
  const [underline,setUnderline]=useState(savedPrefs?.underline??false);
  // 전체 줄을 배너 블록(배경 있는 타이틀 바)으로 감쌀지 여부
  const [wrapBlock,setWrapBlock]=useState(savedPrefs?.wrapBlock??false);
  const [blockBg,setBlockBg]=useState(savedPrefs?.blockBg??"#355C9F");
  const [blockAlign,setBlockAlign]=useState(savedPrefs?.blockAlign??"center");
  const [blockPadding,setBlockPadding]=useState(savedPrefs?.blockPadding??6);

  // 색상·서식을 바꿀 때마다 이 기기에 자동으로 기억해둡니다. (텍스트 내용은 저장 대상 아님)
  useEffect(()=>{
    saveBannerPrefs({styled,color,useBg,bgColor,bold,italic,underline,wrapBlock,blockBg,blockAlign,blockPadding});
  },[styled,color,useBg,bgColor,bold,italic,underline,wrapBlock,blockBg,blockAlign,blockPadding]);

  const segStyleStr=seg=>{
    const parts=[];
    if(seg.styled){
      parts.push(`color:${seg.color}`);
      if(seg.useBg) parts.push(`background-color:${seg.bgColor}`);
      if(seg.bold) parts.push(`font-weight:700`);
      if(seg.italic) parts.push(`font-style:italic`);
      if(seg.underline) parts.push(`text-decoration:underline`);
    }
    return parts.join(";");
  };
  const segReactStyle=seg=>({
    color:seg.styled?seg.color:undefined,
    backgroundColor:seg.styled&&seg.useBg?seg.bgColor:undefined,
    fontWeight:seg.styled&&seg.bold?700:undefined,
    fontStyle:seg.styled&&seg.italic?"italic":undefined,
    textDecoration:seg.styled&&seg.underline?"underline":undefined,
  });

  const addSegment=()=>{
    const t=draftText;if(!t)return;
    setSegments([...segments,{id:newId(),text:t,styled,color,useBg,bgColor,bold,italic,underline}]);
    setDraftText("");
  };
  const removeSegment=id=>setSegments(segments.filter(s=>s.id!==id));

  const buildLine=()=>segments.map(s=>s.styled?`<span style="${segStyleStr(s)}">${s.text}</span>`:s.text).join("");

  const insert=()=>{
    if(segments.length===0)return;
    let line=buildLine();
    if(wrapBlock){
      const blockStyle=`color:#fff;background-color:${blockBg};text-align:${blockAlign};display:block;padding:${blockPadding}px`;
      line=`<span style="${blockStyle}">${line}</span>`;
    }
    onInsert(line);
    setSegments([]);
  };

  return(
    <div className="coc-modal-backdrop" onClick={onClose}>
      <div className="coc-modal" style={{maxWidth:460}} onClick={e=>e.stopPropagation()}>
        <div style={{padding:20}}>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14}}>
            <div className="coc-display" style={{fontSize:16,color:"var(--accent-deep)"}}>배너 만들기</div>
            <button className="coc-btn ghost small" onClick={onClose} style={{padding:6}}><X size={13}/></button>
          </div>

          {/* 완성된 한 줄 미리보기 */}
          <div style={{background:"var(--bg-panel)",border:"1px solid var(--border-soft)",borderRadius:8,padding:12,marginBottom:14,minHeight:20}}>
            <div className="coc-label" style={{marginBottom:6}}>완성된 한 줄</div>
            {segments.length===0?(
              <div style={{fontSize:13,color:"var(--text-faint)"}}>조각을 추가해보세요</div>
            ):(
              <div style={wrapBlock?{color:"#fff",backgroundColor:blockBg,textAlign:blockAlign,display:"block",padding:blockPadding+"px",borderRadius:4}:{fontSize:14}}>
                {segments.map(s=><span key={s.id} style={segReactStyle(s)}>{s.text}</span>)}
              </div>
            )}
          </div>

          {/* 추가된 조각 목록 */}
          {segments.length>0&&(
            <div style={{display:"flex",flexWrap:"wrap",gap:6,marginBottom:14}}>
              {segments.map(s=>(
                <div key={s.id} style={{display:"flex",alignItems:"center",gap:5,background:"#fff",border:"1px solid var(--border)",borderRadius:999,padding:"4px 5px 4px 10px",fontSize:12}}>
                  <span style={segReactStyle(s)}>{s.text}</span>
                  <button type="button" onClick={()=>removeSegment(s.id)} style={{background:"none",border:"none",cursor:"pointer",color:"var(--text-faint)",padding:"0 3px",fontSize:13,lineHeight:1}}>×</button>
                </div>
              ))}
            </div>
          )}

          <div className="coc-divider"/>

          {/* 조각 만들기 */}
          <div className="coc-label" style={{marginBottom:6}}>조각 추가</div>
          <input className="coc-input" value={draftText} onChange={e=>setDraftText(e.target.value)}
            onKeyDown={e=>{if(e.key==="Enter"){e.preventDefault();addSegment();}}}
            placeholder="단어나 문구 입력 (띄어쓰기도 직접 포함해주세요)" style={{marginBottom:10}}/>

          <div style={{display:"flex",alignItems:"center",gap:6,marginBottom:10}}>
            <input type="checkbox" checked={styled} onChange={e=>setStyled(e.target.checked)} style={{width:13,height:13,cursor:"pointer"}}/>
            <span className="coc-label">이 조각에 스타일 적용</span>
          </div>

          {styled&&(
            <div style={{opacity:styled?1:0.4,marginBottom:10}}>
              <div style={{display:"flex",gap:14,marginBottom:10}}>
                <div style={{flex:1}}>
                  <div className="coc-label" style={{marginBottom:5}}>글자색</div>
                  <div style={{display:"flex",alignItems:"center",gap:6}}>
                    <input type="color" value={color} onChange={e=>setColor(e.target.value)} style={{width:30,height:30,border:"1px solid var(--border)",borderRadius:6,padding:0,cursor:"pointer"}}/>
                    <input className="coc-input coc-mono" value={color} onChange={e=>setColor(e.target.value)} style={{fontSize:12}}/>
                  </div>
                </div>
                <div style={{flex:1}}>
                  <div style={{display:"flex",alignItems:"center",gap:5,marginBottom:5}}>
                    <input type="checkbox" checked={useBg} onChange={e=>setUseBg(e.target.checked)} style={{width:13,height:13,cursor:"pointer"}}/>
                    <span className="coc-label">배경색</span>
                  </div>
                  <div style={{display:"flex",alignItems:"center",gap:6,opacity:useBg?1:0.4}}>
                    <input type="color" value={bgColor} onChange={e=>setBgColor(e.target.value)} disabled={!useBg} style={{width:30,height:30,border:"1px solid var(--border)",borderRadius:6,padding:0,cursor:useBg?"pointer":"default"}}/>
                    <input className="coc-input coc-mono" value={bgColor} onChange={e=>setBgColor(e.target.value)} disabled={!useBg} style={{fontSize:12}}/>
                  </div>
                </div>
              </div>
              <div style={{display:"flex",gap:6}}>
                <button type="button" className="coc-btn small" style={{background:bold?"var(--accent)":"#fff",color:bold?"#fff":"var(--text-dim)",border:"1px solid "+(bold?"var(--accent)":"var(--border)"),fontWeight:700}} onClick={()=>setBold(v=>!v)}>B</button>
                <button type="button" className="coc-btn small" style={{background:italic?"var(--accent)":"#fff",color:italic?"#fff":"var(--text-dim)",border:"1px solid "+(italic?"var(--accent)":"var(--border)"),fontStyle:"italic"}} onClick={()=>setItalic(v=>!v)}>I</button>
                <button type="button" className="coc-btn small" style={{background:underline?"var(--accent)":"#fff",color:underline?"#fff":"var(--text-dim)",border:"1px solid "+(underline?"var(--accent)":"var(--border)"),textDecoration:"underline"}} onClick={()=>setUnderline(v=>!v)}>U</button>
              </div>
            </div>
          )}

          <button type="button" className="coc-btn ghost" style={{width:"100%",justifyContent:"center",padding:10,marginBottom:16,borderStyle:"dashed"}} disabled={!draftText} onClick={addSegment}>
            <Plus size={13}/> 이 조각 추가하기
          </button>

          <div className="coc-divider"/>

          {/* 전체 줄을 배너 블록으로 감싸기 (선택) */}
          <div style={{display:"flex",alignItems:"center",gap:6,marginBottom:10}}>
            <input type="checkbox" checked={wrapBlock} onChange={e=>setWrapBlock(e.target.checked)} style={{width:13,height:13,cursor:"pointer"}}/>
            <span className="coc-label">완성된 줄 전체를 타이틀 바처럼 감싸기</span>
          </div>
          {wrapBlock&&(
            <div style={{display:"flex",gap:14,marginBottom:14}}>
              <div style={{flex:1}}>
                <div className="coc-label" style={{marginBottom:5}}>배경색</div>
                <div style={{display:"flex",alignItems:"center",gap:6}}>
                  <input type="color" value={blockBg} onChange={e=>setBlockBg(e.target.value)} style={{width:30,height:30,border:"1px solid var(--border)",borderRadius:6,padding:0,cursor:"pointer"}}/>
                  <input className="coc-input coc-mono" value={blockBg} onChange={e=>setBlockBg(e.target.value)} style={{fontSize:12}}/>
                </div>
              </div>
              <div style={{flex:1}}>
                <div className="coc-label" style={{marginBottom:5}}>정렬</div>
                <div style={{display:"flex",gap:4}}>
                  {[["left","왼"],["center","중"],["right","오"]].map(([v,l])=>(
                    <button key={v} type="button" className="coc-btn small" style={{flex:1,justifyContent:"center",background:blockAlign===v?"var(--accent)":"#fff",color:blockAlign===v?"#fff":"var(--text-dim)",border:"1px solid "+(blockAlign===v?"var(--accent)":"var(--border)")}} onClick={()=>setBlockAlign(v)}>{l}</button>
                  ))}
                </div>
              </div>
            </div>
          )}

          <button type="button" className="coc-btn" style={{width:"100%",justifyContent:"center",padding:11}} disabled={segments.length===0} onClick={insert}>
            채팅 입력창에 삽입
          </button>
          <div style={{fontSize:11.5,color:"var(--text-faint)",marginTop:8,textAlign:"center"}}>
            "조각 추가"로 색이 다른 여러 단어를 계속 쌓은 뒤, 한 번에 삽입하세요.
          </div>
        </div>
      </div>
    </div>
  );
}

function DicePanel({char,onRollToChat}){
  const [open,setOpen]=useState(false);
  const panelRef=useRef(null);

  useEffect(()=>{
    if(!open)return;
    const handler=e=>{if(panelRef.current&&!panelRef.current.contains(e.target))setOpen(false);};
    document.addEventListener("mousedown",handler);
    return()=>document.removeEventListener("mousedown",handler);
  },[open]);

  const roll=(skillName,value)=>{
    const r=d100();
    const{label,color,bg}=calcDiceResult(r,value);
    onRollToChat(JSON.stringify({skillName,value,roll:r,label,color,bg}));
    setOpen(false);
  };

  return(
    <div ref={panelRef} style={{position:"relative",marginLeft:"auto"}}>
      <button type="button" className="coc-btn ghost small" onClick={()=>setOpen(v=>!v)} style={{gap:5,whiteSpace:"nowrap"}}>
        <Dice5 size={12}/> 다이스
      </button>
      {open&&(
        <div className="coc-scroll" style={{position:"absolute",bottom:"calc(100% + 8px)",right:0,width:300,maxHeight:380,overflowY:"auto",background:"#fff",border:"1px solid var(--border)",borderRadius:12,boxShadow:"0 8px 32px rgba(0,0,0,0.14)",padding:"14px 14px 12px",zIndex:20}}>
          <div className="coc-label" style={{marginBottom:8}}>능력치 판정</div>
          <div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:5,marginBottom:12}}>
            {CHAR_KEYS.map(k=>{
              const val=char?.characteristics?.[k]||0;
              return(
                <button key={k} type="button" onClick={()=>roll(CHAR_LABEL[k]+" ("+k+")",val)}
                  style={{background:"var(--bg-panel)",border:"1px solid var(--border-soft)",borderRadius:7,padding:"6px 4px",cursor:"pointer",textAlign:"center"}}
                  onMouseEnter={e=>e.currentTarget.style.borderColor="var(--accent)"}
                  onMouseLeave={e=>e.currentTarget.style.borderColor="var(--border-soft)"}>
                  <div className="coc-mono" style={{fontSize:10,color:"var(--text-faint)"}}>{CHAR_LABEL[k]}</div>
                  <div className="coc-mono" style={{fontSize:14.5,color:"var(--accent-deep)",fontWeight:700}}>{val}</div>
                </button>
              );
            })}
          </div>
          <div className="coc-label" style={{marginBottom:7}}>기능치 판정</div>
          <div style={{display:"grid",gridTemplateColumns:"repeat(2,1fr)",gap:4}}>
            {SKILL_LIST_SORTED.map(([name])=>{
              const val=char?.skills?.[name]??0;
              return(
                <button key={name} type="button" onClick={()=>roll(name,val)}
                  style={{display:"flex",justifyContent:"space-between",alignItems:"center",background:"var(--bg-panel)",border:"1px solid var(--border-soft)",borderRadius:6,padding:"4px 7px",cursor:"pointer"}}
                  onMouseEnter={e=>e.currentTarget.style.background="var(--bg-panel)"}
                  onMouseLeave={e=>e.currentTarget.style.background="var(--bg-panel)"}>
                  <span style={{fontSize:12.5,color:"var(--text-dim)"}}>{name}</span>
                  <span className="coc-mono" style={{fontSize:12,color:"var(--accent-deep)",fontWeight:700}}>{val}</span>
                </button>
              );
            })}
          </div>
          {char?.customSkills?.length>0&&(
            <>
              <div className="coc-label" style={{margin:"10px 0 7px"}}>자유 기능치</div>
              <div style={{display:"grid",gridTemplateColumns:"repeat(2,1fr)",gap:4}}>
                {char.customSkills.filter(c=>c.name).map(c=>(
                  <button key={c.id} type="button" onClick={()=>roll(c.name,c.value||0)}
                    style={{display:"flex",justifyContent:"space-between",alignItems:"center",background:"var(--bg-panel)",border:"1px solid var(--border-soft)",borderRadius:6,padding:"4px 7px",cursor:"pointer"}}>
                    <span style={{fontSize:12.5,color:"var(--text-dim)"}}>{c.name}</span>
                    <span className="coc-mono" style={{fontSize:12,color:"var(--accent-deep)",fontWeight:700}}>{c.value||0}</span>
                  </button>
                ))}
              </div>
            </>
          )}
        </div>
      )}
    </div>
  );
}


function ChatScreen({room,userCode,profile,character,onChangeCharacter,onSwitchCharacter,onBack}){
  const [tabs,setTabs]=useState([{id:"main",label:"메인"}]);
  const [activeTab,setActiveTab]=useState("main");
  const [newTabName,setNewTabName]=useState("");
  const [showAddTab,setShowAddTab]=useState(false);
  const [inviteSelection,setInviteSelection]=useState({}); // {code:true} — 새 탭 생성 시 초대할 대상
  const [tabMsgMaps,setTabMsgMaps]=useState({"main":new Map()});
  const [text,setText]=useState("");
  const [speaker,setSpeaker]=useState("ic");
  const [gmTab,setGmTab]=useState("narrate");
  const [npcName,setNpcName]=useState("");
  const [char,setChar]=useState(character);
  const [editingChar,setEditingChar]=useState(false);
  const [editingMsg,setEditingMsg]=useState(null);
  const [editText,setEditText]=useState("");
  const [bgmUrl,setBgmUrl]=useState("");
  const [bgmInput,setBgmInput]=useState("");
  const [showBgm,setShowBgm]=useState(false);
  // 볼륨은 방(Firestore)에 저장하지 않고 이 기기(브라우저)에만 개인적으로 저장합니다.
  const [bgmVolume,setBgmVolume]=useState(()=>{
    try{
      const v=Number(localStorage.getItem("bgmVolume"));
      return Number.isFinite(v)&&v>=0&&v<=100?v:70;
    }catch{return 70;}
  });
  const iframeRef=useRef(null);
  // 모바일 브라우저는 사용자가 직접 탭하지 않은 자동재생(특히 소리 있는 미디어)을
  // 대부분 차단합니다. 그래서 첫 재생은 반드시 사용자의 탭 한 번을 거치도록 하고,
  // 이후로는(같은 화면에 머무는 동안) URL이 바뀌어도 다시 탭할 필요 없이 이어집니다.
  const [bgmStarted,setBgmStarted]=useState(false);
  const bottomRef=useRef(null);
  const inputRef=useRef(null);
  const imgInputRef=useRef(null);
  const firstLoad=useRef({});
  const isGM=userCode===room.creatorCode;

  // 초대 대상 선택지 + 내 캐릭터 목록(빠른 전환용): 이 방의 캐릭터를 실시간으로 구독합니다.
  const [roomParticipants,setRoomParticipants]=useState([]);
  const [myChars,setMyChars]=useState([]);
  useEffect(()=>{
    const unsub=storeListenPrefix(`char:${room.id}:`,list=>{
      const owners=new Set();
      const mine=[];
      list.forEach(x=>{
        if(x.value.ownerCode&&x.value.ownerCode!==userCode) owners.add(x.value.ownerCode);
        if(x.value.ownerCode===userCode) mine.push(x.value);
      });
      // 방을 만든 GM도 후보에 포함(캐릭터를 아직 안 만들었을 수도 있으므로)
      if(room.creatorCode&&room.creatorCode!==userCode) owners.add(room.creatorCode);
      setRoomParticipants(Array.from(owners));
      setMyChars(mine);
    });
    return()=>unsub();
  },[room.id,room.creatorCode,userCode]);

  // 핸드아웃: GM이 만들고 특정 참가자에게 공개하는 자료(텍스트+사진). 방 전체를 실시간 구독합니다.
  const [handouts,setHandouts]=useState([]);
  useEffect(()=>{
    const unsub=storeListenPrefix(`handout:${room.id}:`,list=>{
      setHandouts(list.map(x=>x.value).sort((a,b)=>(b.createdAt||0)-(a.createdAt||0)));
    });
    return()=>unsub();
  },[room.id]);

  // 접속 상태(온라인 여부): 이 화면을 실제로 보고 있을 때만 주기적으로 "나 여기 있음" 신호를 남기고,
  // 다른 사람의 신호가 최근 것이면(기본 20초 이내) 온라인으로 판단합니다.
  // 모바일에서 앱을 백그라운드로 보내면(화면을 안 보고 있으면) 신호를 안 보내서 자연히 오프라인으로 표시됩니다.
  // 닉네임이 아니라 지금 플레이 중인 캐릭터 이름/사진을 같이 실어보내서 참가자 목록에 표시합니다.
  const ONLINE_THRESHOLD_MS=20000;
  useEffect(()=>{
    const key=`presence:${room.id}:${userCode}`;
    let intervalId=null;
    const beat=()=>{ if(document.visibilityState==="visible") storeSet(key,{userCode,charName:char?.name||userCode,lastSeen:Date.now()},true); };
    const start=()=>{ beat(); if(!intervalId) intervalId=setInterval(beat,10000); };
    const stop=()=>{ if(intervalId){clearInterval(intervalId);intervalId=null;} };
    const onVisibility=()=>{ if(document.visibilityState==="visible") start(); else stop(); };
    start();
    document.addEventListener("visibilitychange",onVisibility);
    return()=>{ stop(); document.removeEventListener("visibilitychange",onVisibility); };
  },[room.id,userCode,char?.name]);

  const [presenceMap,setPresenceMap]=useState({}); // {userCode: {charName,charAvatar,lastSeen}}
  useEffect(()=>{
    const unsub=storeListenPrefix(`presence:${room.id}:`,list=>{
      const map={};
      list.forEach(x=>{ map[x.value.userCode]=x.value; });
      setPresenceMap(map);
    });
    return()=>unsub();
  },[room.id]);
  const isOnline=code=>{
    const last=presenceMap[code]?.lastSeen;
    return !!last&&(Date.now()-last<ONLINE_THRESHOLD_MS);
  };
  // 참가자 목록: 나 + GM + 캐릭터를 만든 다른 사람들 (중복 없이)
  const [showParticipants,setShowParticipants]=useState(false);
  const participantsRef=useRef(null);
  useEffect(()=>{
    if(!showParticipants)return;
    const h=e=>{ if(participantsRef.current&&!participantsRef.current.contains(e.target)) setShowParticipants(false); };
    document.addEventListener("mousedown",h);
    return()=>document.removeEventListener("mousedown",h);
  },[showParticipants]);
  const participantsList=(()=>{
    const set=new Set([userCode]);
    if(room.creatorCode) set.add(room.creatorCode);
    roomParticipants.forEach(c=>set.add(c));
    return Array.from(set).sort((a,b)=>(a===room.creatorCode?-1:b===room.creatorCode?1:0));
  })();
  const myHandouts=handouts.filter(h=>(h.visibleTo||[]).includes(userCode));
  const [showHandoutManager,setShowHandoutManager]=useState(false);
  const [showHandoutViewer,setShowHandoutViewer]=useState(false);
  const [showChoiceCreator,setShowChoiceCreator]=useState(false);
  const [showImgPopover,setShowImgPopover]=useState(false);
  const [imgUrlInput,setImgUrlInput]=useState("");
  const [showBannerBuilder,setShowBannerBuilder]=useState(false);
  const imgPopoverRef=useRef(null);
  useEffect(()=>{
    if(!showImgPopover)return;
    const h=e=>{ if(imgPopoverRef.current&&!imgPopoverRef.current.contains(e.target)) setShowImgPopover(false); };
    document.addEventListener("mousedown",h);
    return()=>document.removeEventListener("mousedown",h);
  },[showImgPopover]);

  function ytEmbedUrl(url){
    if(!url)return null;
    try{
      const u=new URL(url);let v="";
      if(u.hostname.includes("youtu.be"))v=u.pathname.slice(1);
      else if(u.searchParams.get("v"))v=u.searchParams.get("v");
      if(!v)return null;
      return`https://www.youtube.com/embed/${v}?autoplay=1&loop=1&playlist=${v}&controls=1&modestbranding=1&enablejsapi=1`;
    }catch{return null;}
  }

  // 아래 세 가지(탭 목록·채팅 메시지·BGM)는 이전에는 setInterval로 몇 초마다
  // Firestore를 통째로 다시 읽어오는 방식이었는데, 채팅이 길어질수록 무료 요금제의
  // "하루 읽기 5만 건" 한도를 금방 소모했습니다. onSnapshot 실시간 구독으로 바꿔서
  // 최초 1회만 전체를 읽고 이후로는 바뀐 내용만 받아오도록 개선했습니다.

  useEffect(()=>{
    const unsub=storeListenDoc(`tabs:${room.id}`,data=>{
      if(data&&Array.isArray(data)){
        setTabs(data);
        setTabMsgMaps(prev=>{
          const next={...prev};
          data.forEach(t=>{if(!next[t.id])next[t.id]=new Map();});
          return next;
        });
      }
    });
    return()=>unsub();
  },[room.id]);

  // 초대받지 않은 사람에게는 해당 탭이 아예 보이지 않습니다. (GM은 자신이 만든 탭이므로 항상 볼 수 있음)
  const visibleTabs=tabs.filter(t=>isGM||!t.invited||t.invited.includes(userCode));
  useEffect(()=>{
    if(activeTab!=="main"&&!visibleTabs.some(t=>t.id===activeTab)) setActiveTab("main");
  },[activeTab,visibleTabs]);

  // 다른 탭을 봤다가 이 탭으로 돌아왔을 때도 항상 맨 아래(최신 메시지)로 스크롤합니다.
  useEffect(()=>{
    setTimeout(()=>bottomRef.current?.scrollIntoView({block:"end"}),50);
  },[activeTab]);

  useEffect(()=>{
    const prefix=activeTab==="main"?`chat:${room.id}:`:`chat:${room.id}:${activeTab}:`;
    const unsub=storeListenPrefix(prefix,list=>{
      const filtered=activeTab==="main"
        ?list.filter(x=>!x.value.tabId||x.value.tabId==="main")
        :list;
      setTabMsgMaps(prev=>{
        const incoming=new Map();
        for(const{value:m}of filtered)incoming.set(m.id,m);
        // 방금 보낸 메시지가 서버에 아직 반영되기 전에 목록을 다시 읽어오면
        // 순간적으로 화면에서 사라졌다 나타나는 깜빡임이 생길 수 있어서,
        // 8초 이내에 보낸 메시지는 서버 목록에 없어도 잠시 그대로 유지합니다.
        const merged=new Map(incoming);
        const prevMap=prev[activeTab]||new Map();
        const now=Date.now();
        prevMap.forEach((m,id)=>{
          if(!merged.has(id)&&now-m.timestamp<8000) merged.set(id,m);
        });
        return{...prev,[activeTab]:merged};
      });
      if(!firstLoad.current[activeTab]){
        firstLoad.current[activeTab]=true;
        setTimeout(()=>bottomRef.current?.scrollIntoView({block:"end"}),50);
      }
    });
    return()=>unsub();
  },[room.id,activeTab]);

  useEffect(()=>{
    const unsub=storeListenDoc(`bgm:${room.id}`,d=>{ if(d) setBgmUrl(d.url||""); });
    return()=>unsub();
  },[room.id]);

  useEffect(()=>{setChar(character);},[character]);

  const handleSetBgm=async()=>{const url=bgmInput.trim();setBgmUrl(url);await storeSet(`bgm:${room.id}`,{url},true);setBgmInput("");};
  const handleStopBgm=async()=>{setBgmUrl("");await storeSet(`bgm:${room.id}`,{url:""},true);};

  const sendPlayerCommand=(func,args=[])=>{
    try{ iframeRef.current?.contentWindow?.postMessage(JSON.stringify({event:"command",func,args}),"*"); }catch{}
  };

  // 볼륨 변경 시 저장 + 현재 재생 중인 플레이어에 즉시 반영
  useEffect(()=>{
    try{ localStorage.setItem("bgmVolume",String(bgmVolume)); }catch{}
    sendPlayerCommand("setVolume",[bgmVolume]);
  },[bgmVolume]);

  // BGM(영상)이 바뀌어 iframe이 새로 로드될 때도 저장된 볼륨을 재적용
  const handleBgmIframeLoad=()=>{
    setTimeout(()=>sendPlayerCommand("setVolume",[bgmVolume]),500);
    setTimeout(()=>sendPlayerCommand("setVolume",[bgmVolume]),1500);
  };

  const addTab=async()=>{
    const label=newTabName.trim();if(!label)return;
    // 체크한 사람만 볼 수 있는 탭 — 아무도 체크하지 않으면 GM 혼자만 보는 탭이 됩니다.
    const invited=Object.entries(inviteSelection).filter(([,v])=>v).map(([code])=>code);
    const newTab={id:newId(),label,invited,creatorCode:userCode};
    const next=[...tabs,newTab];
    setTabs(next);
    setTabMsgMaps(prev=>({...prev,[newTab.id]:new Map()}));
    await storeSet(`tabs:${room.id}`,next,true);
    setActiveTab(newTab.id);
    setNewTabName("");setShowAddTab(false);setInviteSelection({});
  };
  const removeTab=async(tabId)=>{
    if(tabId==="main")return;
    const next=tabs.filter(t=>t.id!==tabId);
    setTabs(next);
    await storeSet(`tabs:${room.id}`,next,true);
    if(activeTab===tabId)setActiveTab("main");
  };

  const doSend=useCallback(async(sp,msgText,charName,av,tabId)=>{
    const t=msgText.trim();if(!t)return false;
    const tid=tabId||activeTab;
    const msgId=newId();
    const key=tid==="main"?`chat:${room.id}:${msgId}`:`chat:${room.id}:${tid}:${msgId}`;
    const msg={id:msgId,roomId:room.id,userCode,tabId:tid,speaker:sp,characterName:charName,avatar:av||"",text:t,timestamp:Date.now()};
    setTabMsgMaps(prev=>({...prev,[tid]:new Map(prev[tid]||new Map()).set(msg.id,msg)}));
    setTimeout(()=>bottomRef.current?.scrollIntoView({block:"end",behavior:"smooth"}),20);
    storeSet(key,msg,true).then(r=>{if(!r.ok)console.error("저장 실패:",r.error);});
    return true;
  },[room.id,userCode,activeTab]);

  const send=async()=>{
    const raw=text.trim();if(!raw)return;
    const t=resolveInlineDice(raw);
    let ok=false;
    if(isGM&&speaker==="gm"){
      const name=gmTab==="npc"?(npcName.trim()||"NPC"):(profile.name||userCode);
      ok=await doSend(gmTab,t,name,profile.avatar);
    }else{ok=await doSend("ic",t,char.name,char.avatar);}
    if(ok){setText("");setTimeout(()=>inputRef.current?.focus(),10);}
  };

  // 이미지 메시지 전송 공통 로직 (파일 업로드든 외부 링크든 동일하게 처리)
  const postImageMsg=(dataUrlOrLink)=>{
    const tid=activeTab;
    const msgId=newId();
    const key=tid==="main"?`chat:${room.id}:${msgId}`:`chat:${room.id}:${tid}:${msgId}`;
    const msg={id:msgId,roomId:room.id,userCode,tabId:tid,speaker:"image",characterName:char.name||profile.name||userCode,avatar:char.avatar||"",text:dataUrlOrLink,timestamp:Date.now()};
    setTabMsgMaps(prev=>({...prev,[tid]:new Map(prev[tid]||new Map()).set(msg.id,msg)}));
    setTimeout(()=>bottomRef.current?.scrollIntoView({block:"end",behavior:"smooth"}),20);
    storeSet(key,msg,true);
  };
  const sendImage=async(file)=>{
    // 파일을 직접 올릴 땐 PNG로 변환해 투명 배경(알파 채널)을 지킵니다.
    const dataUrl=await fileToResizedPNG(file,480);
    postImageMsg(dataUrl);
  };
  // Imgur 등 외부 링크는 원본 파일을 그대로 불러오므로 리사이즈·재인코딩 없이
  // 투명 배경이 있는 그대로 표시됩니다.
  const sendImageUrl=(url)=>{
    const u=url.trim();if(!u)return;
    postImageMsg(u);
  };

  const sendDice=r=>doSend("dice",r,char.name,char.avatar);
  const handleKeyDown=e=>{if(e.key==="Enter"&&!e.shiftKey){e.preventDefault();send();}};
  const placeholder=()=>{
    if(isGM&&speaker==="gm")return GM_TABS.find(x=>x.key===gmTab)?.placeholder||"";
    return`${char?.name||"캐릭터"}의 대사나 행동을 입력하세요...`;
  };

  const startEdit=msg=>{setEditingMsg(msg);setEditText(msg.text);};
  const submitEdit=async()=>{
    if(!editingMsg||!editText.trim())return;
    const tid=editingMsg.tabId||"main";
    const updated={...editingMsg,text:editText.trim()};
    setTabMsgMaps(prev=>({...prev,[tid]:new Map(prev[tid]||new Map()).set(updated.id,updated)}));
    const key=tid==="main"?`chat:${room.id}:${updated.id}`:`chat:${room.id}:${tid}:${updated.id}`;
    storeSet(key,updated,true);
    setEditingMsg(null);setEditText("");
  };
  const deleteMsg=async msg=>{
    if(!window.confirm("이 메시지를 삭제하시겠습니까?"))return;
    const tid=msg.tabId||"main";
    setTabMsgMaps(prev=>{const m=new Map(prev[tid]||new Map());m.delete(msg.id);return{...prev,[tid]:m};});
    const key=tid==="main"?`chat:${room.id}:${msg.id}`:`chat:${room.id}:${tid}:${msg.id}`;
    storeDelete(key,true);
  };

  // 선택지 버튼을 눌렀을 때: 그 선택지를 고른 사람으로 기록하고, 누른 사람의 캐릭터가
  // "OO을/를 살핀다"라고 말하는 것처럼 채팅에 자동으로 남깁니다.
  const handlePickChoice=async(group,option)=>{
    const msg=group.items[0];
    let data=null; try{data=JSON.parse(msg.text);}catch{return;}
    if(data.picked&&data.picked[option])return; // 이미 누가 고른 선택지면 무시
    const updatedData={...data,picked:{...(data.picked||{}),[option]:{userCode,charName:char?.name||profile.name||userCode}}};
    const tid=msg.tabId||"main";
    const key=tid==="main"?`chat:${room.id}:${msg.id}`:`chat:${room.id}:${tid}:${msg.id}`;
    await storeSet(key,{...msg,text:JSON.stringify(updatedData)},true);
    const charName=char?.name||profile.name||userCode;
    const nameStyled=`<span style="color:var(--accent-deep);font-weight:700">${charName}</span>`;
    const optionStyled=`<span style="color:var(--accent-deep);font-weight:700">${option}</span>`;
    await doSend("system",`${nameStyled}${pickIGa(charName)} ${optionStyled}${pickEulReul(option)} 선택했다`,"","",tid);
  };
  const handleCreateChoice=async(options)=>{
    const payload=JSON.stringify({options,picked:{}});
    await doSend("choice",payload,"","");
    setShowChoiceCreator(false);
  };

  const currentMsgs=Array.from((tabMsgMaps[activeTab]||new Map()).values()).sort((a,b)=>a.timestamp-b.timestamp);
  const groups=groupMessages(currentMsgs);
  const embedUrl=ytEmbedUrl(bgmUrl);
  const speakerBtnStyle=active=>({
    background:active?"var(--accent)":"#fff",
    border:"1px solid "+(active?"var(--accent)":"var(--border)"),
    color:active?"#fff":"var(--text-dim)",
    boxShadow:active?"0 2px 8px rgba(0,0,0,0.12)":"none",
  });

  return(
    <div className="chat-font" style={{maxWidth:740,margin:"0 auto",display:"flex",flexDirection:"column",minHeight:"calc(100vh - 140px)"}}>
      {embedUrl&&bgmStarted&&<iframe ref={iframeRef} src={embedUrl} title="BGM" onLoad={handleBgmIframeLoad} style={{position:"fixed",top:-9999,left:-9999,width:1,height:1,opacity:0,pointerEvents:"none"}} allow="autoplay; encrypted-media"/>}

      {/* 헤더 */}
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:8,flexWrap:"wrap",gap:8}}>
        <div>
          <button className="coc-btn ghost small" onClick={onBack} style={{marginBottom:7}}><ArrowLeft size={12}/> 세션 목록</button>
          <div style={{display:"flex",alignItems:"center",gap:7}}>
            <div className="coc-display" style={{fontSize:16.5,color:"var(--accent-deep)"}}>{room.title}</div>
            {isGM&&<span style={{fontSize:12,fontWeight:700,color:"var(--accent-deep)",fontFamily:"JetBrains Mono,monospace",letterSpacing:"0.05em"}}>GM</span>}
          </div>
          <div className="coc-mono" style={{fontSize:12,color:"var(--text-faint)"}}>{fmtDate(room.date)}</div>
        </div>
        <div style={{display:"flex",alignItems:"center",gap:8,flexWrap:"wrap"}}>
          <button type="button" className="coc-btn ghost small" onClick={()=>setShowBgm(v=>!v)} style={{color:bgmUrl?"var(--accent-deep)":"var(--text-faint)"}}>
            BGM {bgmUrl?(bgmStarted?"재생 중":"탭 필요"):"없음"}
          </button>
          <button type="button" className="coc-btn ghost small" onClick={()=>setShowHandoutViewer(true)} style={{color:myHandouts.length>0?"var(--accent-deep)":"var(--text-faint)"}}>
            핸드아웃{myHandouts.length>0?` (${myHandouts.length})`:""}
          </button>
          <div style={{position:"relative"}} ref={participantsRef}>
            <button type="button" className="coc-btn ghost small" onClick={()=>setShowParticipants(v=>!v)} style={{color:"var(--text-faint)"}}>
              <span style={{color:participantsList.some(c=>c!==userCode&&isOnline(c))?"#e0507a":"var(--border)",marginRight:4,fontSize:11}}>♥</span>
              참가자 ({participantsList.length})
            </button>
            {showParticipants&&(
              <div style={{position:"absolute",top:"calc(100% + 6px)",right:0,zIndex:20,minWidth:180,background:"#fff",border:"1px solid var(--border)",borderRadius:10,boxShadow:"0 8px 24px rgba(0,0,0,0.14)",padding:10}}>
                <div className="coc-label" style={{marginBottom:8}}>참가자</div>
                <div style={{display:"flex",flexDirection:"column",gap:8}}>
                  {participantsList.map(code=>{
                    const online=code===userCode?true:isOnline(code);
                    const displayName=code===userCode?(char?.name||userCode):(presenceMap[code]?.charName||code);
                    return(
                      <div key={code} style={{display:"flex",alignItems:"center",gap:7}}>
                        <span style={{color:online?"#e0507a":"var(--border)",fontSize:13,lineHeight:1,flexShrink:0}}>♥</span>
                        <span style={{fontSize:13,color:online?"var(--text)":"var(--text-faint)",flex:1}}>{displayName}{code===userCode?" (나)":""}</span>
                        {code===room.creatorCode&&<span style={{fontSize:10,fontWeight:700,color:"var(--accent-deep)",fontFamily:"JetBrains Mono,monospace"}}>GM</span>}
                      </div>
                    );
                  })}
                </div>
              </div>
            )}
          </div>
          <div style={{width:32,height:32,borderRadius:"50%",overflow:"hidden",border:"1px solid var(--accent-soft)",background:"var(--bg-panel)"}}>
            {char?.avatar?<img src={char.avatar} style={{width:"100%",height:"100%"}} className="coc-avatar"/>:<Sparkles size={13} color="var(--accent-soft)" style={{margin:9}}/>}
          </div>
          <div>
            <div style={{fontSize:14,fontWeight:600}}>{char?.name}</div>
            <div className="coc-mono" style={{fontSize:10.5,color:"var(--text-faint)"}}>HP {char?.derived?.HP}/{char?.derived?.maxHP} SAN {char?.derived?.SAN}/{char?.derived?.maxSAN}</div>
          </div>
          {myChars.length>1&&(
            <select className="coc-select" value={char?.id||""} title="캐릭터 빠른 전환"
              onChange={e=>{const picked=myChars.find(c=>c.id===e.target.value);if(picked)onSwitchCharacter(picked);}}
              style={{maxWidth:96,fontSize:12,padding:"5px 6px"}}>
              {myChars.map(c=>(<option key={c.id} value={c.id}>{c.name}</option>))}
            </select>
          )}
          <button className="coc-btn ghost small" onClick={()=>setEditingChar(true)}><Pencil size={11}/></button>
          <button className="coc-btn ghost small" onClick={onChangeCharacter}><Users size={11}/></button>
        </div>
      </div>

      {/* BGM 패널 */}
      {showBgm&&(
        <div style={{background:"var(--bg-panel)",border:"1px solid var(--border-soft)",borderRadius:10,padding:"11px 13px",marginBottom:8}}>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:7}}>
            <div className="coc-label">BGM</div>
            <button type="button" onClick={()=>setShowBgm(false)} style={{background:"none",border:"none",cursor:"pointer",color:"var(--text-faint)",padding:2}}><X size={13}/></button>
          </div>
          {bgmUrl&&!bgmStarted&&(
            <button type="button" className="coc-btn small" style={{width:"100%",justifyContent:"center",marginBottom:8}} onClick={()=>setBgmStarted(true)}>
              ▶ 탭해서 재생 시작
            </button>
          )}
          {bgmUrl&&bgmStarted&&<div style={{display:"flex",alignItems:"center",gap:8,marginBottom:8}}>
            <div style={{flex:1,fontSize:13,color:"var(--text-dim)",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{bgmUrl}</div>
            <button type="button" className="coc-btn ghost small" onClick={handleStopBgm}>정지</button>
          </div>}
          {bgmUrl&&bgmStarted&&<div style={{display:"flex",alignItems:"center",gap:8,marginBottom:8}}>
            <span style={{fontSize:12.5,color:"var(--text-dim)",flexShrink:0}}>내 볼륨</span>
            <input type="range" min={0} max={100} value={bgmVolume}
              onChange={e=>setBgmVolume(Number(e.target.value))}
              style={{flex:1,accentColor:"var(--accent)"}}/>
            <span className="coc-mono" style={{fontSize:12,color:"var(--text-faint)",width:26,textAlign:"right",flexShrink:0}}>{bgmVolume}</span>
          </div>}
          {isGM&&<div style={{display:"flex",gap:7}}>
            <input className="coc-input" value={bgmInput} onChange={e=>setBgmInput(e.target.value)} onKeyDown={e=>{if(e.key==="Enter"){e.preventDefault();handleSetBgm();}}} placeholder="YouTube 링크를 붙여넣으세요" style={{flex:1}}/>
            <button type="button" className="coc-btn small" onClick={handleSetBgm} disabled={!bgmInput.trim()}>설정</button>
          </div>}
          {!isGM&&!bgmUrl&&<div style={{fontSize:13.5,color:"var(--text-faint)"}}>GM이 BGM을 설정하면 자동으로 재생됩니다.</div>}
        </div>
      )}

      {/* 채팅 탭바 */}
      <div className="chat-tab-bar">
        {visibleTabs.map(t=>(
          <div key={t.id} style={{display:"flex",alignItems:"center"}}>
            <div className={"chat-tab"+(activeTab===t.id?" active":"")} onClick={()=>setActiveTab(t.id)}>
              {t.invited&&t.invited.length>0&&<span style={{marginRight:3,fontSize:11}}>🔒</span>}
              {t.label}
            </div>
            {isGM&&t.id!=="main"&&(
              <button type="button" onClick={()=>removeTab(t.id)} style={{background:"none",border:"none",cursor:"pointer",color:"var(--text-faint)",padding:"0 4px",fontSize:15,lineHeight:1,opacity:0.5}}>×</button>
            )}
          </div>
        ))}
        {isGM&&(
          showAddTab?(
            <div style={{display:"flex",alignItems:"center",gap:6,padding:"4px 6px",flexWrap:"wrap"}}>
              <input value={newTabName} onChange={e=>setNewTabName(e.target.value)}
                onKeyDown={e=>{if(e.key==="Enter"){e.preventDefault();addTab();}if(e.key==="Escape")setShowAddTab(false);}}
                placeholder="탭 이름" autoFocus
                style={{width:90,fontSize:13,padding:"3px 7px",border:"1px solid var(--border)",borderRadius:5,outline:"none",color:"var(--text)",background:"#fff"}}/>
              {/* 초대 대상 선택 — 체크 안 하면 GM만 보이는 탭이 됨 */}
              <div style={{display:"flex",gap:6,alignItems:"center",flexWrap:"wrap"}}>
                {roomParticipants.length===0&&<span style={{fontSize:12,color:"var(--text-faint)"}}>초대할 참가자가 아직 없어요</span>}
                {roomParticipants.map(code=>(
                  <label key={code} style={{display:"flex",alignItems:"center",gap:3,fontSize:12.5,color:"var(--text-dim)",cursor:"pointer"}}>
                    <input type="checkbox" checked={!!inviteSelection[code]}
                      onChange={e=>setInviteSelection(prev=>({...prev,[code]:e.target.checked}))}
                      style={{width:13,height:13,cursor:"pointer"}}/>
                    {code} 초대
                  </label>
                ))}
              </div>
              <button type="button" className="coc-btn small" style={{padding:"3px 8px",fontSize:12}} onClick={addTab} disabled={!newTabName.trim()}>추가</button>
              <button type="button" className="coc-btn ghost small" style={{padding:"3px 6px"}} onClick={()=>{setShowAddTab(false);setInviteSelection({});}}><X size={10}/></button>
            </div>
          ):(
            <div className="chat-tab" onClick={()=>setShowAddTab(true)} style={{opacity:0.5,cursor:"pointer",display:"flex",alignItems:"center",gap:2}}><Plus size={10}/> 탭 추가</div>
          )
        )}
      </div>

      {/* 메시지 목록 — GM 서브탭/NPC 이름 입력창 등이 아래에 추가로 나타나도
          이 영역 크기는 항상 일정하게 유지됩니다. 화면에 다 안 들어가면
          이 영역 안이 아니라 페이지 전체가 스크롤됩니다. */}
      <div className="coc-card coc-scroll" style={{height:"46vh",minHeight:220,maxHeight:520,flexShrink:0,overflowY:"auto",padding:"12px 14px",display:"flex",flexDirection:"column",gap:1}}>
        {groups.length===0&&(
          <div style={{margin:"auto",color:"var(--text-faint)",fontSize:13.5,textAlign:"center"}}>
            <MessageCircle size={20} style={{marginBottom:7,opacity:0.5}}/><br/>아직 기록이 없습니다. 첫 문장을 남겨보세요.
          </div>
        )}
        {groups.map(g=><MessageBlock key={g.id} group={g} myUserCode={userCode} isGM={isGM} onEdit={startEdit} onDelete={deleteMsg} onPickChoice={handlePickChoice}/>)}
        <div ref={bottomRef}/>
      </div>

      {/* 메시지 수정 모달 */}
      {editingMsg&&(
        <div className="coc-modal-backdrop" onClick={()=>setEditingMsg(null)}>
          <div className="coc-modal" style={{maxWidth:460}} onClick={e=>e.stopPropagation()}>
            <div style={{padding:18}}>
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:12}}>
                <div className="coc-display" style={{fontSize:15,color:"var(--accent-deep)"}}>메시지 수정</div>
                <button className="coc-btn ghost small" onClick={()=>setEditingMsg(null)} style={{padding:5}}><X size={12}/></button>
              </div>
              <textarea className="coc-input" rows={4} value={editText} onChange={e=>setEditText(e.target.value)} autoFocus style={{marginBottom:12}}/>
              <div style={{display:"flex",gap:8,justifyContent:"flex-end"}}>
                <button className="coc-btn ghost small" onClick={()=>setEditingMsg(null)}>취소</button>
                <button className="coc-btn small" onClick={submitEdit} disabled={!editText.trim()}>수정 완료</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* 입력창 */}
      <div style={{marginTop:8}}>
        <div style={{display:"flex",gap:5,marginBottom:6,flexWrap:"wrap"}}>
          <button type="button" className="coc-btn small" style={speakerBtnStyle(speaker==="ic")} onClick={()=>setSpeaker("ic")}><Sparkles size={11}/> {char?.name||"캐릭터"}</button>
          {isGM&&<button type="button" className="coc-btn small" style={speakerBtnStyle(speaker==="gm")} onClick={()=>setSpeaker("gm")}><Crown size={11}/> GM</button>}
          {isGM&&(
            <div ref={imgPopoverRef} style={{position:"relative"}}>
              <button type="button" className="coc-btn ghost small" onClick={()=>setShowImgPopover(v=>!v)}>이미지 전송</button>
              {showImgPopover&&(
                <div style={{position:"absolute",top:"calc(100% + 6px)",left:0,zIndex:20,width:230,background:"#fff",border:"1px solid var(--border)",borderRadius:10,boxShadow:"0 8px 24px rgba(0,0,0,0.14)",padding:10}}>
                  <button type="button" className="coc-btn ghost small" style={{width:"100%",justifyContent:"center",marginBottom:8}} onClick={()=>imgInputRef.current?.click()}>
                    파일에서 선택
                  </button>
                  <div style={{display:"flex",gap:6}}>
                    <input className="coc-input" value={imgUrlInput} onChange={e=>setImgUrlInput(e.target.value)}
                      onKeyDown={e=>{if(e.key==="Enter"){e.preventDefault();sendImageUrl(imgUrlInput);setImgUrlInput("");setShowImgPopover(false);}}}
                      placeholder="이미지 링크 (Imgur 등)" style={{flex:1,fontSize:12.5}}/>
                    <button type="button" className="coc-btn small" disabled={!imgUrlInput.trim()}
                      onClick={()=>{sendImageUrl(imgUrlInput);setImgUrlInput("");setShowImgPopover(false);}}>
                      삽입
                    </button>
                  </div>
                </div>
              )}
              <input ref={imgInputRef} type="file" accept="image/*" style={{display:"none"}}
                onChange={async e=>{const f=e.target.files?.[0];if(!f)return;await sendImage(f);e.target.value="";setShowImgPopover(false);}}/>
            </div>
          )}
          {isGM&&<button type="button" className="coc-btn ghost small" onClick={()=>setShowBannerBuilder(true)}>배너 만들기</button>}
          <DicePanel char={char} onRollToChat={sendDice}/>
        </div>
        {/* GM 전용: 서술·판정·대사·선택지·핸드아웃 다섯 칸이 바게트처럼 하나로 이어진 바 */}
        {isGM&&speaker==="gm"&&(
          <div style={{display:"flex",border:"1px solid var(--border)",borderRadius:10,overflow:"hidden",marginBottom:8}}>
            {GM_TABS.map(({key,short},i)=>(
              <button key={key} type="button"
                onClick={()=>{
                  setGmTab(key);
                  if(key==="choice") setShowChoiceCreator(true);
                  if(key==="handout") setShowHandoutManager(true);
                }}
                style={{
                  flex:1,padding:"9px 4px",border:"none",
                  borderLeft:i===0?"none":"1px solid var(--border)",
                  background:gmTab===key?"var(--accent)":"#fff",
                  color:gmTab===key?"#fff":"var(--text-dim)",
                  fontSize:12.5,fontWeight:gmTab===key?700:500,cursor:"pointer",
                }}>
                {short}
              </button>
            ))}
          </div>
        )}
        {isGM&&speaker==="gm"&&gmTab==="npc"&&(
          <input className="coc-input" value={npcName} onChange={e=>setNpcName(e.target.value)} placeholder="NPC 이름 (미입력 시 'NPC')" style={{marginBottom:6}}/>
        )}
        {isGM&&speaker==="gm"&&(gmTab==="choice"||gmTab==="handout")?(
          <div style={{fontSize:12.5,color:"var(--text-faint)",padding:"10px 2px"}}>
            위 {gmTab==="choice"?"'선택'":"'H/O'"} 버튼을 눌러 {gmTab==="choice"?"선택지를 만들어보세요.":"핸드아웃을 관리해보세요."}
          </div>
        ):(
          <>
            <div style={{display:"flex",gap:7}}>
              <textarea ref={inputRef} className="coc-input" rows={2} value={text}
                onChange={e=>setText(e.target.value)} onKeyDown={handleKeyDown}
                placeholder={placeholder()} style={{flex:1,resize:"none"}}/>
              <button type="button" className="coc-btn" style={{flexShrink:0,alignSelf:"flex-end",padding:"10px 14px"}} onClick={send}><Send size={13}/></button>
            </div>
            <div style={{fontSize:12,color:"var(--text-faint)",marginTop:4}}>Enter: 전송 · Shift+Enter: 줄바꿈</div>
          </>
        )}
      </div>

      {editingChar&&<CharacterEditModal initial={{id:char.id,sheet:char,createdAt:char.createdAt}} roomId={room.id} userCode={userCode} onClose={()=>setEditingChar(false)} onSaved={c=>{setChar(c);setEditingChar(false);}}/>}
      {showChoiceCreator&&<ChoiceCreatorModal onClose={()=>setShowChoiceCreator(false)} onCreate={handleCreateChoice}/>}
      {showHandoutManager&&<HandoutManagerModal room={room} userCode={userCode} handouts={handouts} roomParticipants={roomParticipants} onClose={()=>setShowHandoutManager(false)}/>}
      {showHandoutViewer&&<HandoutViewerModal handouts={myHandouts} onClose={()=>setShowHandoutViewer(false)}/>}
      {showBannerBuilder&&(
        <BannerBuilderModal
          onClose={()=>setShowBannerBuilder(false)}
          onInsert={markup=>setText(prev=>prev?prev+"\n"+markup:markup)}
        />
      )}
    </div>
  );
}

/* ============================== ERROR BOUNDARY ============================== */
// 렌더링 중 에러가 나면 하얀 화면 대신 실제 에러 내용을 화면에 보여줍니다.
class ErrorBoundary extends React.Component {
  constructor(props){ super(props); this.state = { error: null, info: null }; }
  static getDerivedStateFromError(error){ return { error }; }
  componentDidCatch(error, info){ this.setState({ info }); console.error("[TRPG APP CRASH]", error, info); }
  render(){
    if (this.state.error) {
      return (
        <div style={{minHeight:"100vh",padding:20,fontFamily:"monospace",background:"#fff5f5",color:"#7a1a1a"}}>
          <div style={{fontWeight:700,fontSize:17,marginBottom:10}}>⚠️ 화면에 에러가 발생했습니다</div>
          <div style={{marginBottom:14}}>
            <button
              onClick={()=>this.setState({error:null,info:null})}
              style={{padding:"6px 12px",marginRight:8,cursor:"pointer"}}>
              다시 시도
            </button>
          </div>
          <div style={{fontSize:14.5,fontWeight:700,marginBottom:6}}>{String(this.state.error && this.state.error.message)}</div>
          <pre style={{whiteSpace:"pre-wrap",fontSize:12.5,background:"#fff",border:"1px solid #eab",borderRadius:6,padding:12,overflowX:"auto"}}>
{String(this.state.error && this.state.error.stack)}
          </pre>
          {this.state.info && (
            <details style={{marginTop:10}}>
              <summary style={{cursor:"pointer",fontSize:13.5}}>컴포넌트 스택 보기</summary>
              <pre style={{whiteSpace:"pre-wrap",fontSize:12.5,background:"#fff",border:"1px solid #eab",borderRadius:6,padding:12,overflowX:"auto"}}>
{this.state.info.componentStack}
              </pre>
            </details>
          )}
        </div>
      );
    }
    return this.props.children;
  }
}

/* ============================== APP ============================== */

function AppInner(){
  const [user,setUser]=useState(null);
  const [authChecked,setAuthChecked]=useState(false);
  const [tab,setTab]=useState("rooms");
  const [profile,setProfile]=useState(blankProfile());
  const [profileLoaded,setProfileLoaded]=useState(false);
  const [activeRoom,setActiveRoom]=useState(null);
  const [activeChar,setActiveChar]=useState(null);
  const [themeKey,setThemeKey]=useState("sky");
  const [customColor,setCustomColor]=useState("#2e9bdb");

  // 앱을 처음 열었을 때, 이 기기에 저장된 로그인 정보가 있으면 자동으로 다시 로그인합니다.
  useEffect(()=>{
    (async()=>{
      const saved=loadRememberedAuth();
      if(!saved){ setAuthChecked(true); return; }
      const existing=await storeGet(`user:${saved.username}`,true);
      if(existing&&existing.passwordHash===saved.passwordHash){
        setUser({code:saved.username,name:saved.username});
      }else{
        clearRememberedAuth();
      }
      setAuthChecked(true);
    })();
  },[]);

  useEffect(()=>{
    if(!user)return;
    (async()=>{
      const p=await storeGet(`profile:${user.code}`,true);
      setProfile(p||blankProfile(user.name));
      setProfileLoaded(true);
      // 저장된 테마 불러오기 (shared:true, 코드별 키)
      // 예전 형식(문자열 "sky" 등)과 새 형식({key:"custom",color:"#.."}) 둘 다 지원
      const t=await storeGet(`theme:${user.code}`,true);
      if(typeof t==="string"&&THEMES[t]){
        setThemeKey(t);
      }else if(t&&typeof t==="object"&&t.key==="custom"&&isValidHexColor(t.color)){
        setThemeKey("custom");setCustomColor(t.color);
      }else if(t&&typeof t==="object"&&THEMES[t.key]){
        setThemeKey(t.key);
      }else{
        setThemeKey("sky"); // 기본값 강제
      }
    })();
  },[user]);

  const handleThemePreset=k=>{
    setThemeKey(k);
    if(user) storeSet(`theme:${user.code}`,{key:k},true);
  };
  const handleThemeCustom=hex=>{
    if(!isValidHexColor(hex))return;
    setThemeKey("custom");
    setCustomColor(hex);
    if(user) storeSet(`theme:${user.code}`,{key:"custom",color:hex},true);
  };

  const theme=themeKey==="custom"?deriveThemeFromColor(customColor):(THEMES[themeKey]||THEMES.sky);

  if(!authChecked) return(
    <div className="coc-root" style={themeVars(theme)}>
      <style>{CSS}</style>
    </div>
  );

  if(!user) return(
    <div className="coc-root" style={themeVars(theme)}>
      <style>{CSS}</style>
      <AuthScreen onLogin={setUser}/>
    </div>
  );

  const logout=()=>{clearRememberedAuth();setUser(null);setActiveRoom(null);setActiveChar(null);setTab("rooms");};

  let body;
  if(activeRoom&&!activeChar){
    body=<CharacterSelectScreen room={activeRoom} userCode={user.code} onSelect={c=>setActiveChar(c)} onBack={()=>setActiveRoom(null)}/>;
  }else if(activeRoom&&activeChar){
    body=<ChatScreen room={activeRoom} userCode={user.code} profile={profile} character={activeChar} onChangeCharacter={()=>setActiveChar(null)} onSwitchCharacter={c=>setActiveChar(c)} onBack={()=>{setActiveRoom(null);setActiveChar(null);}}/>;
  }else if(tab==="settings"){
    body=<SettingsTab currentTheme={themeKey} customColor={customColor} onSelectPreset={handleThemePreset} onSelectCustom={handleThemeCustom}/>;
  }else if(tab==="profile"){
    body=profileLoaded&&<MyPage userCode={user.code} profile={profile} setProfile={setProfile}/>;
  }else{
    body=<RoomsTab userCode={user.code} onEnterRoom={r=>setActiveRoom(r)}/>;
  }

  return(
    <div className="coc-root" style={themeVars(theme)}>
      <style>{CSS}</style>
      <div style={{position:"relative",zIndex:1,padding:"20px 16px 56px"}}>
        {!activeRoom&&(
          <div style={{maxWidth:680,margin:"0 auto 22px",display:"flex",justifyContent:"space-between",alignItems:"center",flexWrap:"wrap",gap:10}}>
            <div style={{display:"flex",alignItems:"center",gap:8}}>
              <span className="coc-display heart-font" style={{fontSize:22,color:"var(--accent-deep)"}}>Heart Emoji</span>
              <span style={{fontSize:12.5,color:"var(--text-faint)",marginLeft:6}}>· {profile.name||user.name}님</span>
            </div>
            <div style={{display:"flex",alignItems:"center",gap:12,flexWrap:"wrap"}}>
              <div className="coc-tabbar">
                <div className={"coc-tab"+(tab==="rooms"?" active":"")} onClick={()=>setTab("rooms")}>세션</div>
                <div className={"coc-tab"+(tab==="profile"?" active":"")} onClick={()=>setTab("profile")}>마이페이지</div>
                <div className={"coc-tab"+(tab==="settings"?" active":"")} onClick={()=>setTab("settings")}>설정</div>
              </div>
              <button className="coc-btn ghost small" onClick={logout}><LogOut size={11}/> 로그아웃</button>
            </div>
          </div>
        )}
        {body}
      </div>
    </div>
  );
}

export default function App(){
  return (
    <ErrorBoundary>
      <AppInner/>
    </ErrorBoundary>
  );
}
